# THE ONKELOS ROWS of Numbers 4:21-7:89 (THE NUMBERS WALK sitting 2 — NASO, 2026-09-09): verdict and prose per verse, the Aramaic and the
# Hebrew CUT by consonants (naso_ink.H / naso_ink.A — every miss collected, asserted empty by the writer). Speed ruling (c): the twelve
# offering blocks after Nahshon's are verdicted verse by verse in one line each, their identity to 7:13-17 COMPUTED (naso_ink.DIFFS).
# Every quotation is SHORT and glossed at once (the gloss lint's window is ninety characters per Hebrew word — the first draft's long
# quotations were split into pieces, each with its English).
from naso_ink import *
R = {}
def row(c, v, verdict, prose): R[(c, v)] = (verdict, prose)

# ---- 4:21-49 — Gershon and Merari counted; the four work-counts ----
row(4, 21, 'CONTEXT', 'The frame: "and the LORD spoke to Moses, saying" — the first of the portion\'s eight (computed), to Moses alone (the chapter\'s earlier frames 4:1 and 4:17 were to Moses AND Aaron).')
row(4, 22, 'MATERIAL', f'THEM ALSO. "{H(4, 22, "נשא", "את", "ראש", "בני", "גרשון", "גם", "הם")}" ("lift the head of the sons of Gershon, them also") → {A(4, 22, "קבל", "ית", "חשבן", "בני", "גרשון", "אף", "אנון")} ("receive the sum of the sons of Gershon, they too") — the census idiom\'s infinitive form at its second and last seat (computed: 4:2 Kohath, 4:22 Gershon; Merari at 4:29 is counted without the idiom), the accounting rendering held.')
row(4, 23, 'MATERIAL', f'THE HOST OF THE WORK, DOUBLED. "{H(4, 23, "כל", "הבא", "לצבא", "צבא", "לעבד", "עבדה")}" ("everyone who comes to host the host, to work the work") → {A(4, 23, "כל", "דאתי", "לחילא", "חילא", "למפלח", "פלחנא")} ("everyone who comes to the host a host, to serve a service") — the two cognate doublings kept in the Aramaic; the window thirty-to-fifty repeated (4:23, 30, 35, 39, 43, 47 — computed with 4:3).')
row(4, 24, 'CONTEXT', f'"This is the service of the families of the Gershonite, to serve and to carry" → {A(4, 24, "למפלח", "ולמטול")} ("to serve and to carry") — the two verbs that name the two services of 4:47.')
row(4, 25, 'MATERIAL', f'GERSHON\'S LOAD IS THE SOFT. The curtains of the tabernacle, the tent, its covering, "{H(4, 25, "ומכסה", "התחש")}" ("and the tachash covering") on top, and the screen of the door → {A(4, 25, "וחופאה", "דססגונא")} ("and the sasgona covering") — the colored-hide word of 4:6 again; the woven inventory of 3:25-26 now assigned as a burden.')
row(4, 26, 'CONTEXT', f'The court hangings, the gate screen, the ropes, "all that will be delivered to them" → {A(4, 26, "וית", "כל", "די", "יתמסר", "להון")} ("and all that will be handed over to them").')
row(4, 27, 'MATERIAL', f'BY THE MOUTH OF AARON; APPOINTED BY CHARGE. "{H(4, 27, "על", "פי", "אהרן", "ובניו")}" ("by the mouth of Aaron and his sons") shall be all the service of the Gershonites → {A(4, 27, "על", "מימר", "אהרן", "ובנוהי")} ("by the word of Aaron and his sons"); "{H(4, 27, "ופקדתם", "עלהם", "במשמרת")}" ("and you shall appoint over them by charge") → {A(4, 27, "ותמנון", "עליהון", "במטרא")} ("and you shall appoint over them by watch") — the priests assign, the Levites bear, as at 4:19.')
row(4, 28, 'MATERIAL', f'ITHAMAR\'S HAND. "{H(4, 28, "ביד", "איתמר")}" ("in the hand of Ithamar") → {A(4, 28, "בידא", "דאיתמר")} ("in the hand of Ithamar") — Gershon and Merari under Ithamar (4:28, 4:33 — computed), Kohath\'s holy things under Eleazar (4:16, the chapter\'s one Eleazar — computed): the two surviving sons hold the two portfolios, the soft and the hard against the holy.')
row(4, 29, 'CONTEXT', 'Merari "by their families, by their fathers\' house you shall count them" — no "lift the head" (computed: the idiom at 4:2 and 4:22 only).')
row(4, 30, 'CONTEXT', 'The window repeated: from thirty to fifty, "everyone who comes to the host to serve the service of the tent of meeting".')
row(4, 31, 'MATERIAL', f'MERARI\'S LOAD IS THE HARD. "{H(4, 31, "וזאת", "משמרת", "משאם")}" ("and this is the charge of their burden"): the frames, the bars, the pillars, the sockets → {A(4, 31, "דפי", "משכנא", "ועברוהי", "ועמודוהי", "וסמכוהי")} ("the boards of the tabernacle and its bars and its pillars and its sockets") — 3:36-37\'s inventory as a burden; the charge-word on a load.')
row(4, 32, 'MATERIAL', f'THE VESSELS BY NAMES. "{H(4, 32, "ובשמת", "תפקדו", "את", "כלי", "משמרת", "משאם")}" ("and by names you shall appoint the vessels of the charge of their burden") → {A(4, 32, "ובשמהן", "תמנון", "ית", "מני", "מטרת", "מטולהון")} ("and by names you shall appoint the vessels of the watch of their burden") — the census\'s count-of-names (1:2) turned on VESSELS: each socket and pin assigned to a named man.')
row(4, 33, 'CONTEXT', 'Merari\'s closing formula, "in the hand of Ithamar son of Aaron the priest" — the second Ithamar (computed).')
row(4, 34, 'MATERIAL', f'THE PRINCES JOIN THE COUNT. "{H(4, 34, "ויפקד", "משה", "ואהרן", "ונשיאי", "העדה")}" ("and Moses and Aaron and the princes of the congregation counted") → {A(4, 34, "ומנא", "משה", "ואהרן", "ורברבי", "כנשתא")} ("and Moses and Aaron and the great ones of the assembly counted") — the twelve of 1:4-16 stand over this count too (4:34 "of the congregation", 4:46 "of Israel" — computed); 7:2 names them by this: "they who stood over the counted".')
row(4, 35, 'CONTEXT', 'The window on the Kohathites counted.')
row(4, 36, 'MATERIAL', f'KOHATH\'S WORKERS: {numword(WORK["kohath"][0])}. "{H(4, 36, "אלפים", "שבע", "מאות", "וחמשים")}" ("thousands, seven hundred and fifty") → {A(4, 36, "תרין", "אלפין", "שבע", "מאה", "וחמשין")} ("TWO thousand seven hundred and fifty") — the Hebrew DUAL carries the two; the Aramaic writes it (the parser\'s dual rule of sitting 1b, confirmed by the translation); against 3:28\'s 8,600 from a month up: {SHARE["kohath"]} of a hundred are of working age (computed).')
row(4, 37, 'MATERIAL', f'BY THE MOUTH OF THE LORD, BY THE HAND OF MOSES. "{H(4, 37, "על", "פי", "יהוה", "ביד", "משה")}" ("by the mouth of the LORD by the hand of Moses") → {A(4, 37, "על", "מימרא", "דיי", "בידא", "דמשה")} ("by the Word of the LORD by the hand of Moses") — the formula with "the hand" at 4:37, 4:45, 4:49; WITHOUT it at 4:41 (computed).')
row(4, 38, 'CONTEXT', 'Gershon\'s count opens: by families, by fathers\' house.')
row(4, 39, 'CONTEXT', 'The window on the Gershonites counted.')
row(4, 40, 'MATERIAL', f'GERSHON\'S WORKERS: {numword(WORK["gershon"][0])}. "{H(4, 40, "אלפים", "ושש", "מאות", "ושלשים")}" ("thousands and six hundred and thirty") → {A(4, 40, "תרין", "אלפין", "ושית", "מאה", "ותלתין")} ("two thousand and six hundred and thirty") — against 3:22\'s 7,500: {SHARE["gershon"]} of a hundred (computed).')
row(4, 41, 'MATERIAL', f'THE FORMULA WITHOUT THE HAND. "{H(4, 41, "על", "פי", "יהוה")}" ("by the mouth of the LORD") and no "by the hand of Moses" — the one of the four closing formulas so written (computed) → {A(4, 41, "על", "מימרא", "דיי")} ("by the Word of the LORD"); recorded, no reason drawn.')
row(4, 42, 'CONTEXT', 'Merari\'s count opens.')
row(4, 43, 'CONTEXT', 'The window on the Merarites counted.')
row(4, 44, 'MATERIAL', f'MERARI\'S WORKERS: {numword(WORK["merari"][0])}. "{H(4, 44, "שלשת", "אלפים", "ומאתים")}" ("three thousand and two hundred") → {A(4, 44, "תלתא", "אלפין", "ומאתן")} ("three thousand and two hundred") — the smallest house (3:34\'s 6,200) gives the LARGEST working share, {SHARE["merari"]} of a hundred (computed): the frame-carriers.')
row(4, 45, 'CONTEXT', 'The closing formula on Merari, with "the hand of Moses" (computed).')
row(4, 46, 'MATERIAL', f'THE PRINCES OF ISRAEL. "{H(4, 46, "משה", "ואהרן", "ונשיאי", "ישראל")}" ("Moses and Aaron and the princes of Israel") → {A(4, 46, "משה", "ואהרן", "ורברבי", "ישראל")} ("Moses and Aaron and the great ones of Israel") — the counters named a second time, "of Israel" for 4:34\'s "of the congregation" (computed).')
row(4, 47, 'MATERIAL', f'THE SERVICE OF SERVICE. "{H(4, 47, "לעבד", "עבדת", "עבדה", "ועבדת", "משא")}" ("to work the service of service and the service of burden") → {A(4, 47, "למפלח", "פלחן", "פלחנא", "ופלחן", "מטול")} ("to serve the service of service and the service of carrying") — the doubled cognate kept as a doubled cognate: the exam\'s Arakhin 11a reads "a service for another service" as the SONG (routed).')
row(4, 48, 'MATERIAL', f'THE TOTAL IS THE SUM: {numword(WORK_TOTAL[0])}. "{H(4, 48, "שמנת", "אלפים", "וחמש", "מאות", "ושמנים")}" ("eight thousand and five hundred and eighty") → {A(4, 48, "תמניא", "אלפין", "וחמש", "מאה", "ותמנן")} ("eight thousand and five hundred and eighty") — the three work-counts summed equal it (computed by the ENGINE\'S OWN PARSER, taught the census at sitting 1b: {numword(WORK["kohath"][0])} + {numword(WORK["gershon"][0])} + {numword(WORK["merari"][0])}); against 3:39\'s 22,000 from a month up — the sitting-1b parser\'s first proof on new ink.')
row(4, 49, 'MATERIAL', f'EACH MAN, EACH MAN. "{H(4, 49, "על", "פי", "יהוה", "פקד", "אותם", "ביד", "משה")}" ("by the mouth of the LORD he counted them by the hand of Moses"), "{H(4, 49, "איש", "איש", "על", "עבדתו", "ועל", "משאו")}" ("each man, each man to his service and to his burden") → {A(4, 49, "גבר", "גבר", "על", "פלחניה", "ועל", "מטוליה")} ("each man, each man to his service and to his burden") — 4:19\'s doubled man returns at the chapter\'s close; "{H(4, 49, "ופקדיו", "אשר", "צוה", "יהוה", "את", "משה")}" ("and his counted ones which the LORD commanded Moses") → {A(4, 49, "ומנינוהי", "די", "פקיד", "יי", "ית", "משה")} ("and his numbered ones which the LORD commanded Moses") — the spec/run pair of the work-count closed with both formulas (4:49 = the run of 4:22-33).')

# ---- 5:1-10 — the camp purified; the theft; the gifts ----
row(5, 1, 'CONTEXT', 'The frame (the second of eight — computed).')
row(5, 2, 'MATERIAL', f'THE THREE SENT OUT. "{H(5, 2, "צו", "את", "בני", "ישראל")}" ("command the children of Israel"), "{H(5, 2, "וישלחו", "מן", "המחנה")}" ("that they send out of the camp"), "{H(5, 2, "כל", "צרוע", "וכל", "זב", "וכל", "טמא", "לנפש")}" ("every leper and every one with a discharge and every one unclean by a soul") → {A(5, 2, "כל", "דסגיר", "וכל", "דדאב")} ("every one SHUT UP and every one who FLOWS"), {A(5, 2, "וכל", "דמסאב", "לטמי", "נפשא", "דאנשא")} ("and every one unclean by the corpse of a man\'s soul") — the leper named by the priest\'s act of Leviticus 13 (the quarantine verb, "he shall shut him up"), the zav by his flow, the corpse-unclean with the object expanded to "of a man"; "command" → {A(5, 2, "פקיד")} ("command"); the camp-word once here, twice at 5:3 — three in the command (computed; the Sifrei\'s three camps, piska 1 row 7).')
row(5, 3, 'MATERIAL', f'FROM MALE TO FEMALE; MY SHEKHINAH IN THEIR MIDST. "{H(5, 3, "מזכר", "עד", "נקבה", "תשלחו")}" ("from male to female you shall send out" — the phrase\'s one seat, computed) → {A(5, 3, "מדכר", "עד", "נוקבא", "תשלחון")} ("from male to female you shall send out"); "{H(5, 3, "אל", "מחוץ", "למחנה", "תשלחום")}" ("outside the camp you shall send them") → {A(5, 3, "למברא", "למשריתא", "תשלחנון")} ("outside the camp you shall send them"); "{H(5, 3, "אשר", "אני", "שכן", "בתוכם")}" ("in whose midst I dwell" — with 35:34 the Torah\'s two seats of the dwelling clause, computed) → {A(5, 3, "די", "שכנתי", "שריא", "ביניהון")} ("in whose midst MY SHEKHINAH dwells") — the first person rendered by the Presence-word; the Sifrei\'s "beloved are Israel — even unclean, the Shekhinah among them" (piska 1 row 7) is the translation\'s own noun.')
row(5, 4, 'MATERIAL', f'THE RUN, DOUBLED. "{H(5, 4, "ויעשו", "כן", "בני", "ישראל")}" ("and the children of Israel did so"), "{H(5, 4, "וישלחו", "אותם", "אל", "מחוץ", "למחנה")}" ("and sent them outside the camp"), "{H(5, 4, "כאשר", "דבר", "יהוה", "אל", "משה", "כן", "עשו", "בני", "ישראל")}" ("as the LORD spoke to Moses, so the children of Israel did") → {A(5, 4, "ועבדו", "כן", "בני", "ישראל")} ("and the children of Israel did so"), {A(5, 4, "כמא", "די", "מליל", "יי", "עם", "משה", "כן", "עבדו", "בני", "ישראל")} ("as the LORD spoke with Moses, so the children of Israel did") — "so" twice, "the children of Israel" twice in one report (computed): the portion\'s first spec/run pair (5:2-3 → 5:4) and its only narrative act before 7:1 (the register, computed); the Sifrei reads the doubling as the unclean not protesting (piska 1 row 8).')
row(5, 5, 'CONTEXT', 'The frame (the third of eight).')
row(5, 6, 'MATERIAL', f'A MAN OR A WOMAN; ANY SIN OF MAN; TO LIE A LIE. "{H(5, 6, "איש", "או", "אשה", "כי", "יעשו", "מכל", "חטאת", "האדם")}" ("a man or a woman, if they do of any of the sins of man" — the phrase\'s one seat, computed) → {A(5, 6, "גבר", "או", "אתתא", "ארי", "יעבדון", "מכל", "חובי", "אנשא")} ("a man or a woman, if they do of any of the sins of man"); "{H(5, 6, "למעל", "מעל", "ביהוה")}" ("to commit a trespass against the LORD") → {A(5, 6, "לשקרא", "שקר", "קדם", "יי")} ("TO LIE A LIE before the LORD") — the translation renders trespass (me\'ilah) as LYING: the Sifrei\'s own lemma rule, "me\'ilah in all places is lying" (piska 2 row 1; piska 7 row 1), is the Aramaic word. THE NOUN BY ITS POINTS: מַעַל ("trespass", a patach — the short a-vowel — under both letters) at {len(MAAL_NOUN)} Tanakh seats — Lev 5:15, 5:21, Num 5:6, 5:27, 31:16, Josh 7:1 among them — against מֵעַל ("from upon", a tsere — the long e-vowel) at {MAAL_FROM}: the same consonants, two words, told apart as sitting 1b told "from" from "a hundred of".')
row(5, 7, 'MATERIAL', f'CONFESS, RESTORE AT ITS HEAD, ADD ITS FIFTH. "{H(5, 7, "והתודו", "את", "חטאתם", "אשר", "עשו")}" ("and they shall confess their sin which they did") → {A(5, 7, "ויודון", "ית", "חוביהון", "די", "עבדו")} ("and they shall confess their sins which they did"); "{H(5, 7, "והשיב", "את", "אשמו", "בראשו")}" ("and he shall restore his guilt at its head" — the principal) → {A(5, 7, "ויתב", "ית", "חובתיה", "ברישיה")} ("and he shall return his debt at its head"); "{H(5, 7, "וחמישתו", "יסף", "עליו")}" ("and its fifth he shall add to it") — the fifth-clause\'s Torah seats {", ".join(FIFTH)} (computed: the guilt offering, the false oath, the redeemed consecration, and here); "{H(5, 7, "ונתן", "לאשר", "אשם", "לו")}" ("and give it to him against whom he is guilty") → {A(5, 7, "ויתן", "לדחב", "ליה")} ("and give it to him whom he owes").')
row(5, 8, 'MATERIAL', f'NO REDEEMER: THE LORD\'S, TO THE PRIEST. "{H(5, 8, "ואם", "אין", "לאיש", "גאל", "להשיב", "האשם", "אליו")}" ("and if the man has no redeemer to restore the guilt to") → {A(5, 8, "ואם", "לית", "לגבר", "פריק")} ("and if the man has no redeemer") — the kinsman-redeemer word of Leviticus 25 (the Sifrei: who in Israel has no kinsman? the proselyte who died — piska 4 row 1); "{H(5, 8, "האשם", "המושב", "ליהוה", "לכהן")}" ("the guilt restored is the LORD\'s, to the priest" — the phrase\'s one seat, computed) → {A(5, 8, "חובתא", "דמתב", "קדם", "יי", "לכהנא")} ("the debt returned is before the LORD, to the priest"); "{H(5, 8, "מלבד", "איל", "הכפרים")}" ("besides the ram of atonements" — one seat, computed) → {A(5, 8, "בר", "מדכר", "כפוריא")} ("besides the ram of atonements").')
row(5, 9, 'MATERIAL', f'EVERY HEAVE-OFFERING TO THE PRIEST. "{H(5, 9, "וכל", "תרומה", "לכל", "קדשי", "בני", "ישראל")}" ("and every heave-offering of all the holy things of the children of Israel"), "{H(5, 9, "אשר", "יקריבו", "לכהן", "לו", "יהיה")}" ("which they bring near to the priest, shall be his") → {A(5, 9, "וכל", "אפרשותא", "לכל", "קודשיא")} ("and every SET-APART portion of all the holy things") — the terumah rendered by the separating-word; the Sifrei\'s first-fruits reading of "which they bring near" (piska 5 row 1).')
row(5, 10, 'MATERIAL', f'A MAN\'S HOLY THINGS ARE HIS — THE TITHE INSERTED. "{H(5, 10, "ואיש", "את", "קדשיו", "לו", "יהיו")}" ("and a man, his holy things shall be his" — one seat, computed) → {A(5, 10, "וגבר", "ית", "מעשר", "קודשיה", "דליה", "יהון")} ("and a man, THE TITHE of his holy things shall be his") — a word the Hebrew does not have, cut from the shelf\'s bytes: the translation names WHICH holy thing stays the owner\'s, the tithe (the Sifrei\'s list of what Scripture left the owners — second tithe among them — piska 6 row 1; the same row\'s neta revai dispute); "{H(5, 10, "איש", "אשר", "יתן", "לכהן", "לו", "יהיה")}" ("what a man gives to the priest shall be his") → {A(5, 10, "גבר", "דיתן", "לכהנא", "דליה", "יהא")} ("a man who gives to the priest, his shall it be") — the Sifrei\'s refrain (piskaot 4 and 6).')

# ---- 5:11-31 — the suspected wife ----
row(5, 11, 'CONTEXT', 'The frame (the fourth of eight).')
row(5, 12, 'MATERIAL', f'A MAN, A MAN; SHE LIES A LIE. "{H(5, 12, "איש", "איש", "כי", "תשטה", "אשתו")}" ("a man, a man, if his wife go astray") — the doubled man\'s four Torah seats {", ".join(ISH_ISH)} (computed) → {A(5, 12, "גבר", "גבר", "ארי", "תסטי", "אתתיה")} ("a man, a man, if his wife go astray"); "{H(5, 12, "ומעלה", "בו", "מעל")}" ("and commit a trespass against him") → {A(5, 12, "ותשקר", "ביה", "שקר")} ("and LIE against him a lie") — me\'ilah is lying again, the verb\'s pausal form {MAAL_VERB512} ("she trespassed") the verse\'s last word; the Sifrei\'s "in the area of illicit relations, not money" (piska 7 row 1).')
row(5, 13, 'MATERIAL', f'THE SIX CONDITIONS. "{H(5, 13, "ושכב", "איש", "אתה", "שכבת", "זרע")}" ("and a man lie with her a lying of seed"), "{H(5, 13, "ונעלם", "מעיני", "אישה")}" ("and it be hidden from her husband\'s eyes"), "{H(5, 13, "ונסתרה", "והיא", "נטמאה")}" ("and she be secreted and she be defiled"), "{H(5, 13, "ועד", "אין", "בה")}" ("and there is no witness against her" — one seat, computed), "{H(5, 13, "והוא", "לא", "נתפשה")}" ("and she was not seized" — the Torah\'s one seat, computed) → {A(5, 13, "וסהיד", "לית", "בה", "והיא", "לא", "אתחדת")} ("and there is no witness in her and she was not taken") — the Sifrei reads each: not a minor, not her sister, the husband not unseeing, the secreting\'s minimum, "witness" = two, the forced excluded (piska 7 rows 2-3).')
row(5, 14, 'MATERIAL', f'THE SPIRIT OF JEALOUSY; DEFILED OR NOT. "{H(5, 14, "ועבר", "עליו", "רוח", "קנאה", "וקנא", "את", "אשתו")}" ("and a spirit of jealousy pass over him and he be jealous of his wife" — 5:14 and 5:30, computed) → {A(5, 14, "רוח", "קנאה")} ("a spirit of jealousy"); "{H(5, 14, "והיא", "נטמאה")}" ("and she is defiled") ... "{H(5, 14, "והיא", "לא", "נטמאה")}" ("and she is not defiled") — both arms in one verse: the DOUBT is the case (the Sifrei: she drinks only in doubt, and the doubt-rule of purity is built on it — piska 7 row 3).')
row(5, 15, 'MATERIAL', f'THE OFFERING: A TENTH OF THE EPHAH, BARLEY MEAL, NO OIL, NO FRANKINCENSE, A MEMORIAL OF INIQUITY. "{H(5, 15, "עשירת", "האיפה", "קמח", "שערים")}" ("a tenth of the ephah of barley meal") — the plene spelling האיפה ("the ephah", with the yod) here and at Exod 16:36, Num 28:5 against Leviticus\' defective האפה ("the ephah", without it — 5:11, 6:13; computed); קמח ("meal") at two Torah seats, Sarah\'s (Gen 18:6) and this (computed) → {A(5, 15, "חד", "מן", "עסרא", "בתלת", "סאין", "קמחא", "שערין")} ("one of ten in THREE SE\'AH of barley meal") — THE EPHAH CONVERTED: the translation writes the ephah as three se\'ah, the conversion layer on a dry measure (the exam\'s Menachot 77a); "{H(5, 15, "לא", "יצק", "עליו", "שמן", "ולא", "יתן", "עליו", "לבנה")}" ("he shall not pour oil on it nor put frankincense on it") — Lev 5:11\'s sinner\'s-offering clause with a different verb (there "he shall not PUT oil", here "POUR" — computed); "{H(5, 15, "מנחת", "קנאת", "הוא")}" ("an offering of jealousies it is"), "{H(5, 15, "מנחת", "זכרון", "מזכרת", "עון")}" ("an offering of memorial, a reminder of iniquity" — both phrases alone in the Tanakh, computed) → {A(5, 15, "מנחת", "קנאתא", "הוא")} ("an offering of jealousy it is"), {A(5, 15, "מנחת", "דוכרנא", "מדכרת", "חובא")} ("an offering of memorial, a reminder of guilt").')
row(5, 16, 'MATERIAL', f'BROUGHT NEAR AND STOOD. "{H(5, 16, "והקריב", "אתה", "הכהן", "והעמדה", "לפני", "יהוה")}" ("and the priest shall bring her near and stand her before the LORD") → {A(5, 16, "ויקרב", "יתה", "כהנא", "ויקימנה", "קדם", "יי")} ("and the priest shall bring her near and stand her before the LORD") — the offering verb on the woman; the Sifrei: not two together, not with her servants, at the Nicanor gate (piska 9).')
row(5, 17, 'MATERIAL', f'HOLY WATER IS THE LAVER\'S; AN EARTHEN VESSEL; THE FLOOR\'S DUST. "{H(5, 17, "מים", "קדשים")}" ("holy water" — one seat, computed) → {A(5, 17, "מי", "כיור")} ("WATER OF THE LAVER") — the translation names the vessel the ink leaves unnamed; the Sifrei says the same, "water consecrated in a vessel, the laver\'s" (piska 10); "{H(5, 17, "בכלי", "חרש")}" ("in an earthen vessel" — the vessel\'s six Torah seats {", ".join(CHERES)}, computed; the Sifrei\'s identity with Lev 14:5\'s bird-vessel → a new one) → {A(5, 17, "במן", "דחסף")} ("in a vessel of clay"); "{H(5, 17, "ומן", "העפר", "אשר", "יהיה", "בקרקע", "המשכן")}" ("and of the dust that is on the floor of the tabernacle") → {A(5, 17, "ומן", "עפרא", "די", "יהי", "ביסודי", "משכנא")} ("and of the dust that is in the FOUNDATIONS of the tabernacle") — the floor as its base.')
row(5, 18, 'MATERIAL', f'THE HEAD UNCOVERED; ON HER PALMS; THE BITTER CURSING WATERS. "{H(5, 18, "ופרע", "את", "ראש", "האשה")}" ("and he shall uncover the woman\'s head") — the root\'s six Torah seats {"; ".join(PARA)} (computed: the calf\'s "let loose", the priests\' heads, the leper\'s, the high priest\'s, the wife\'s, the nazirite\'s locks) → {A(5, 18, "ויפרע", "ית", "רישא", "דאתתא")} ("and he shall uncover the head of the woman"); "{H(5, 18, "ונתן", "על", "כפיה")}" ("and put on her palms" — with 6:19\'s "on the nazirite\'s palms" the portion\'s two palm-verses, computed); "{H(5, 18, "מי", "המרים", "המאררים")}" ("the bitter cursing waters" — 5:18, 19, 24, computed) → {A(5, 18, "מיא", "מריריא", "מלטטיא")} ("the bitter, CURSING waters") — the passive participle rendered active.')
row(5, 19, 'MATERIAL', f'THE OATH OPENS FOR MERIT. "{H(5, 19, "והשביע", "אתה", "הכהן")}" ("and the priest shall adjure her") → {A(5, 19, "ויומי", "יתה", "כהנא")} ("and the priest shall adjure her") — the priest swears her, she does not swear (the Sifrei, piska 12); "{H(5, 19, "אם", "לא", "שכב", "איש", "אתך")}" ("if no man has lain with you"), "{H(5, 19, "ואם", "לא", "שטית", "טמאה", "תחת", "אישך", "הנקי")}" ("and if you have not gone astray to uncleanness under your husband, be clean") → {A(5, 19, "הוי", "זכאה")} ("be innocent") — the clean arm first; "under your husband" at 5:19, 5:20 and "under her husband" at 5:29 (computed; Ezek 16:32 the one seat outside).')
row(5, 20, 'MATERIAL', f'THE GUILTY ARM. "{H(5, 20, "ואת", "כי", "שטית", "תחת", "אישך", "וכי", "נטמאת")}" ("and you, if you have gone astray under your husband and if you are defiled"), "{H(5, 20, "ויתן", "איש", "בך", "את", "שכבתו", "מבלעדי", "אישך")}" ("and a man has put his lying in you besides your husband") → {A(5, 20, "ויהב", "גבר", "ביך", "ית", "שכבתיה", "בר", "מבעליך")} ("and a man has put in you his lying besides your husband") — the register\'s "and he gave" INSIDE the oath (the narrative-past form in a curse — computed); the Sifrei\'s inclusions from the clause (piska 13).')
row(5, 21, 'MATERIAL', f'THE OATH OF THE CURSE; THIGH FIRST. "{H(5, 21, "והשביע", "הכהן", "את", "האשה", "בשבעת", "האלה")}" ("and the priest shall adjure the woman with the oath of the curse") → {A(5, 21, "במומתא", "דלוטא")} ("with the oath of the curse"); "{H(5, 21, "יתן", "יהוה", "אותך", "לאלה", "ולשבעה", "בתוך", "עמך")}" ("the LORD make you a curse and an oath in the midst of your people" — one seat, computed) → {A(5, 21, "ללוט", "ולמומי", "בגו", "עמיך")} ("a curse and an oath in the midst of your people"); "{H(5, 21, "את", "ירכך", "נפלת", "ואת", "בטנך", "צבה")}" ("your thigh falling and your belly swelling") — THIGH BEFORE BELLY here; belly before thigh at 5:22 and 5:27 (computed) — the Sifrei reads the reversal as the adulterer\'s limbs (piska 15 row 1) → {A(5, 21, "ית", "ירכיך", "מסיא", "וית", "מעיכי", "נפיחין")} ("your thigh wasting and your bowels swollen").')
row(5, 22, 'MATERIAL', f'BELLY FIRST; AMEN, AMEN. "{H(5, 22, "ובאו", "המים", "המאררים", "האלה", "במעיך")}" ("and these cursing waters shall come into your bowels"), "{H(5, 22, "לצבות", "בטן", "ולנפל", "ירך")}" ("to swell belly and to make thigh fall") → {A(5, 22, "לאפחא", "מעין", "ולאמסאה", "ירכא")} ("to swell the bowels and to waste the thigh"); "{H(5, 22, "ואמרה", "האשה", "אמן", "אמן")}" ("and the woman shall say amen, amen") — the bare doubled amen at two Tanakh seats, {" and ".join(AMEN)} (computed; the Psalms\' "amen and amen" carries the conjunction) → {A(5, 22, "ותימר", "אתתא", "אמן", "אמן")} ("and the woman shall say amen, amen") — kept; the Sifrei\'s two amens, on the oath and on the curse (piska 12; 15 rows 1-2).')
row(5, 23, 'MATERIAL', f'WRITTEN IN A SCROLL, ERASED INTO THE WATER. "{H(5, 23, "וכתב", "את", "האלת", "האלה", "הכהן", "בספר")}" ("and the priest shall write these curses in a scroll"), "{H(5, 23, "ומחה", "אל", "מי", "המרים")}" ("and erase into the bitter water") → {A(5, 23, "ויכתוב", "ית", "לוטיא", "האלין", "כהנא", "בספרא")} ("and the priest shall write these curses in a scroll"), {A(5, 23, "וימחוק", "למיא", "מריריא")} ("and erase into the bitter water") — the one Torah command to ERASE what is written in holiness; the verb\'s Torah seats: Deut 29:19 (a sinner\'s NAME blotted) and this (computed; Num 34:11\'s "and reach" is the consonantal homograph); the Sifrei: a scroll, ink, the Name erased for peace (piska 16).')
row(5, 24, 'MATERIAL', f'THE DRINKING. "{H(5, 24, "והשקה", "את", "האשה", "את", "מי", "המרים", "המאררים")}" ("and he shall make the woman drink the bitter cursing waters"), "{H(5, 24, "ובאו", "בה", "המים", "המאררים", "למרים")}" ("and the cursing waters shall enter her for bitterness") → {A(5, 24, "ויעלון", "בה", "מיא", "מלטטיא", "למרירו")} ("and the cursing waters shall enter her for bitterness"); the drinking commanded here and again at 5:26-27 (the Sifrei\'s three seats: R. Akiva\'s forced drinking, R. Shimon\'s three requirements — piska 17).')
row(5, 25, 'MATERIAL', f'WAVED — RENDERED LIFTED. "{H(5, 25, "ולקח", "הכהן", "מיד", "האשה", "את", "מנחת", "הקנאת")}" ("and the priest shall take from the woman\'s hand the offering of jealousies"), "{H(5, 25, "והניף", "את", "המנחה", "לפני", "יהוה")}" ("and wave the offering before the LORD"), "{H(5, 25, "והקריב", "אתה", "אל", "המזבח")}" ("and bring it near to the altar") → {A(5, 25, "וירים", "ית", "מנחתא", "קדם", "יי")} ("and LIFT the offering before the LORD") — the waving verb rendered by the lifting verb (again at 6:20: the Aramaic has one verb where the Hebrew has two; the Sifrei compares lifting to waving — piska 17; 37); "from the hand of the woman" — not her agent (piska 17).')
row(5, 26, 'MATERIAL', f'THE FISTFUL, THEN THE DRINK. "{H(5, 26, "וקמץ", "הכהן", "מן", "המנחה", "את", "אזכרתה")}" ("and the priest shall take a fistful from the offering, its memorial"), "{H(5, 26, "והקטיר", "המזבחה")}" ("and burn it on the altar"), "{H(5, 26, "ואחר", "ישקה", "את", "האשה", "את", "המים")}" ("and AFTER he shall make the woman drink the water") → {A(5, 26, "ויקמוץ", "כהנא", "מן", "מנחתא", "ית", "אדכרתה")} ("and the priest shall take a fistful from the offering, its memorial"), {A(5, 26, "ויסק", "למדבחא", "ובתר", "כן", "ישקי")} ("and burn it on the altar, and after that he shall make her drink") — the fistful\'s "memorial" is Lev 2:2\'s word on the meal offering; the ORDER written: the burning, then the drinking (the Sifrei\'s three categorical requirements — piska 17).')
row(5, 27, 'MATERIAL', f'THE OUTCOME IF DEFILED. "{H(5, 27, "והשקה", "את", "המים", "והיתה", "אם", "נטמאה")}" ("and he shall make her drink the water, and it shall be, if she is defiled"), "{H(5, 27, "ותמעל", "מעל", "באישה")}" ("and has trespassed a trespass against her husband") → {A(5, 27, "ושקרת", "שקר", "בבעלה")} ("and LIED a lie against her husband") — the register\'s "and she trespassed" a narrative-past inside the law (computed); "{H(5, 27, "וצבתה", "בטנה", "ונפלה", "ירכה")}" ("and her belly shall swell and her thigh fall" — belly first, computed) → {A(5, 27, "ויפחון", "מעהא", "ותתמסי", "ירכה")} ("and her bowels shall swell and her thigh waste"); "{H(5, 27, "והיתה", "האשה", "לאלה", "בקרב", "עמה")}" ("and the woman shall be a curse in the midst of her people") → {A(5, 27, "ללוט", "בגו", "עמה")} ("a curse in the midst of her people"); the Sifrei: from the limb where the sin began (piska 18).')
row(5, 28, 'MATERIAL', f'THE OUTCOME IF CLEAN: CLEARED, AND SEED. "{H(5, 28, "ואם", "לא", "נטמאה", "האשה", "וטהרה", "הוא")}" ("and if the woman is not defiled and she is clean"), "{H(5, 28, "ונקתה", "ונזרעה", "זרע")}" ("she shall be cleared and shall be sown with seed" — the last clause\'s one seat, computed) → {A(5, 28, "ותפוק", "זכאה", "ותעדי", "עדוי")} ("and she shall go out innocent and shall CONCEIVE a conception") — the seed rendered as conception: the translation takes R. Yishmael\'s reading (if barren, she conceives) that R. Akiva refutes in the Sifrei (piska 19, the row headed "5:298" — the head\'s mistyped digit, the row on 5:28 by position and by its own quotation).')
row(5, 29, 'MATERIAL', f'THIS IS THE LAW OF JEALOUSIES. "{H(5, 29, "זאת", "תורת", "הקנאת")}" ("this is the law of jealousies") → {A(5, 29, "דא", "אוריתא", "דקנאתא")} ("this is the law of jealousy") — the formula\'s first of three in the portion (5:29, 6:13, 6:21 — computed among the Torah\'s {len(ZOT_TORAT)}; the Sifrei\'s R. Yoshiyah / R. Yonathan on each: for all generations / a summation — piskaot 20, 32, 38); "{H(5, 29, "אשר", "תשטה", "אשה", "תחת", "אישה", "ונטמאה")}" ("when a wife goes astray under her husband and is defiled") — the ONE "and she is defiled" with the conjunction in the section (computed: the root\'s eight tokens — נטמאה ("she is defiled") at 5:13, twice at 5:14, 5:27, 5:28; טמאה ("defiled") at 5:19; נטמאת ("you are defiled") at 5:20; ונטמאה ("and she is defiled") at 5:29), R. Akiva\'s three counted on the shelf (piska 7 row 3).')
row(5, 30, 'MATERIAL', f'OR A MAN — OBLIGATORY. "{H(5, 30, "או", "איש", "אשר", "תעבר", "עליו", "רוח", "קנאה")}" ("or a man over whom a spirit of jealousy passes"), "{H(5, 30, "וקנא", "את", "אשתו")}" ("and he is jealous of his wife"), "{H(5, 30, "והעמיד", "את", "האשה", "לפני", "יהוה")}" ("then he shall stand the woman before the LORD"), "{H(5, 30, "ועשה", "לה", "הכהן", "את", "כל", "התורה", "הזאת")}" ("and the priest shall do to her all this law") → {A(5, 30, "ויעבד", "לה", "כהנא", "ית", "כל", "אוריתא", "הדא")} ("and the priest shall do to her all this law") — the second seat of the jealousy-spirit (computed); the Sifrei: the repetition makes the drinking obligatory, not optional (piska 21).')
row(5, 31, 'MATERIAL', f'THE MAN CLEAN, THE WOMAN BEARS. "{H(5, 31, "ונקה", "האיש", "מעון")}" ("and the man shall be clean of iniquity"), "{H(5, 31, "והאשה", "ההוא", "תשא", "את", "עונה")}" ("and that woman shall bear her iniquity" — the clause\'s one seat, computed) → {A(5, 31, "ויהי", "זכאה", "גברא", "מחובא")} ("and the man shall be innocent of sin"), {A(5, 31, "ואתתא", "ההיא", "תקבל", "ית", "חובה")} ("and that woman shall RECEIVE her sin") — the cleared-root thrice in the section: "be clean" 5:19, "she shall be cleared" 5:28, "the man shall be clean" 5:31 (computed); the Sifrei\'s Hosea reading: the waters test the wife only when the husband is clean (piska 21).')

# ---- 6:1-21 — the Nazirite ----
row(6, 1, 'CONTEXT', 'The frame (the fifth of eight).')
row(6, 2, 'MATERIAL', f'THE VOW DECLARED; NAZIR. "{H(6, 2, "איש", "או", "אשה", "כי", "יפלא", "לנדר", "נדר")}" ("a man or a woman, if he declares to vow a vow"), "{H(6, 2, "נזיר", "להזיר", "ליהוה")}" ("of a nazirite, to separate to the LORD") → {A(6, 2, "ארי", "יפרש", "למדר", "נדר", "נזירו")} ("if he SET APART to vow a vow of nazirship"), {A(6, 2, "למיזר", "קדם", "יי")} ("to separate before the LORD") — the declaring verb\'s Torah seats {", ".join(YAFLI)} (computed; the infinitive at {", ".join(LEFALE)} — the Sifrei\'s identity with Lev 22:21\'s vows: willingly); נזיר ("nazirite") at nine Torah seats — Joseph\'s two (Gen 49:26, Deut 33:16), the untrimmed vine (Lev 25:5), and this chapter\'s six (computed; the Sifrei: "nezirah in all places is separation" — piska 23).')
row(6, 3, 'MATERIAL', f'WINE AND STRONG DRINK — RENDERED NEW AND OLD. "{H(6, 3, "מיין", "ושכר", "יזיר")}" ("from wine and strong drink he shall separate") → {A(6, 3, "מחמר", "חדת", "ועתיק", "יזר")} ("from wine NEW and OLD he shall separate") — the translation\'s reading of the pair beside the Sifrei\'s two ("the Torah speaks in two tongues" / R. Elazar Hakappar: diluted and undiluted — piska 23): three readings on one shelf, RECORDED, none chosen; "{H(6, 3, "חמץ", "יין", "וחמץ", "שכר", "לא", "ישתה")}" ("vinegar of wine and vinegar of strong drink he shall not drink") → {A(6, 3, "חל", "דחמר", "חדת", "וחל", "דחמר", "עתיק")} ("vinegar of new wine and vinegar of old wine"); "{H(6, 3, "וכל", "משרת", "ענבים", "לא", "ישתה")}" ("and any steeping of grapes he shall not drink") — מִשְׁרַת ("steeping") the one seat of that pointing against מְשָׁרֵת ("minister") at seven (computed by the points: the same consonants) → {A(6, 3, "וכל", "מתרות", "ענבין")} ("and any steeping of grapes"); "{H(6, 3, "וענבים", "לחים", "ויבשים", "לא", "יאכל")}" ("and grapes moist and dry he shall not eat") → {A(6, 3, "וענבין", "רטיבין", "ויבשין")} ("and grapes moist and dry").')
row(6, 4, 'MATERIAL', f'FROM KERNELS TO SKIN. "{H(6, 4, "כל", "ימי", "נזרו")}" ("all the days of his separation"), "{H(6, 4, "מכל", "אשר", "יעשה", "מגפן", "היין")}" ("of all that is made from the vine of wine"), "{H(6, 4, "מחרצנים", "ועד", "זג", "לא", "יאכל")}" ("from kernels to skin he shall not eat") — both words alone in the Tanakh (computed) → {A(6, 4, "מפורצנין", "ועד", "עצורין")} ("from the pips to the PRESSED skins"); the Sifrei\'s general-particular on the clause and R. Yehudah / R. Yossi on which is which (piska 24).')
row(6, 5, 'MATERIAL', f'NO RAZOR; HOLY; THE LOCKS GROW. "{H(6, 5, "תער", "לא", "יעבר", "על", "ראשו")}" ("a razor shall not pass over his head" — the clause\'s one seat, computed; Samson\'s and Samuel\'s "no razor shall come up" with another word) → {A(6, 5, "מספר", "לא", "יעבר", "על", "רישיה")} ("a SHEARING BLADE shall not pass over his head"); "{H(6, 5, "עד", "מלאת", "הימם")}" ("until the days are fulfilled" — the fulfilling-word at 6:5 and 6:13, computed); "{H(6, 5, "קדש", "יהיה", "גדל", "פרע", "שער", "ראשו")}" ("holy shall he be, growing the locks of the hair of his head") → {A(6, 5, "קדיש", "יהי", "מרבי", "פרוע", "שער", "רישיה")} ("holy shall he be, growing the loose hair of his head") — the locks-word is the leper\'s "his head shall be loosed" (Lev 13:45) and the wife\'s "he shall uncover her head" (5:18): the root\'s six Torah seats (computed); the Sifrei\'s identity nazirite-leper on it, and its thirty days from the letters of "he shall be" (piska 25).')
row(6, 6, 'MATERIAL', f'UPON A DEAD SOUL HE SHALL NOT COME. "{H(6, 6, "כל", "ימי", "הזירו", "ליהוה")}" ("all the days of his separating to the LORD"), "{H(6, 6, "על", "נפש", "מת", "לא", "יבא")}" ("upon a dead soul he shall not come") — one seat; the high priest\'s "upon all dead souls he shall not come" (Lev 21:11) its pair (computed) → {A(6, 6, "על", "נפשא", "דמתא", "לא", "ייעול")} ("upon a dead soul he shall not ENTER") — the translation\'s verb is entry: R. Yishmael\'s reading in the Sifrei ("he shall not come" — a soul that defiles by entry, a man\'s, not a beast\'s — piska 26).')
